def removeOuterParentheses(S: str) -> str:
    result = []
    depth = 0  # Track current nesting depth

    for c in S:
        if c == '(':
            if depth > 0:
                result.append('(')  # Only add if not the outermost '('
            depth += 1
        elif c == ')':
            depth -= 1
            if depth > 0:
                result.append(')')  # Only add if not the outermost ')'

    return ''.join(result)
